import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry inputSchema validation', () => {
  it('rejects input missing a required property before calling the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn<() => Promise<string>>().mockResolvedValue('sunny');
    registry.register(
      {
        name: 'require_location',
        description: 'Requires a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      executor
    );

    const response = await registry.execute('require_location', {});
    const executorCalls = executor.mock.calls;

    expect({result: response.result, executorCalls: executorCalls.length}).toEqual({
      result: expect.stringMatching(/location.*required|required.*location/i),
      executorCalls: 0,
    });
  });

  it('reports the path and expected type for a rejected typed property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'find_user',
        description: 'Find a user by email',
        inputSchema: {type: 'object', properties: {email: {type: 'string'}}, required: ['email']},
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('find_user', {email: 42});

    expect(response.result).toMatch(/email.*string/i);
  });

  it('names the rejected property when Ajv reports a legacy dataPath', async () => {
    const registry = new ToolRegistry();
    const validator = Object.assign(
      jest.fn(() => false),
      {
        errors: [{keyword: 'type', dataPath: '.email', message: 'should be string'}],
      }
    );
    Object.defineProperty(registry, 'schemaValidator', {value: {compile: () => validator}});
    registry.register(
      {
        name: 'find_member',
        description: 'Find a member by email',
        inputSchema: {type: 'object', properties: {email: {type: 'string'}}, required: ['email']},
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('find_member', {email: 42});

    expect(response.result).toMatch(/email.*string/i);
  });

  it('passes input that violates an out-of-contract schema constraint to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn<() => Promise<string>>().mockResolvedValue('sunny');
    registry.register(
      {
        name: 'short_location',
        description: 'Gets weather for a short location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string', minLength: 3}},
          required: ['location'],
        },
      },
      executor
    );

    const input = {location: 'NY'};
    const response = await registry.execute('short_location', input);

    expect({response, executorCalls: executor.mock.calls}).toEqual({
      response: {result: 'sunny'},
      executorCalls: [[input, undefined]],
    });
  });

  it('names the complete path for a missing nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'find_contact',
        description: 'Finds a contact by email',
        inputSchema: {
          type: 'object',
          properties: {
            contact: {type: 'object', properties: {email: {type: 'string'}}, required: ['email']},
          },
          required: ['contact'],
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('find_contact', {contact: {}});

    expect(response.result).toMatch(/contact.*email.*required/i);
  });

  it('rejects an invalid properties schema at register time and names the tool', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'invalid_properties',
          description: 'Has an invalid schema',
          inputSchema: {type: 'object', properties: 'not-an-object'},
        },
        async () => 'unreachable'
      )
    ).toThrow(/invalid_properties/i);
  });

  it('compiles a static schema once and reuses it across executions', async () => {
    const registry = new ToolRegistry();
    const schemaValidator = (registry as unknown as {schemaValidator: {compile: (...args: never[]) => unknown}})
      .schemaValidator;
    const compile = jest.spyOn(schemaValidator, 'compile');
    registry.register(
      {
        name: 'static_location',
        description: 'Gets weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      async () => 'sunny'
    );

    await Promise.all(Array.from({length: 10}, () => registry.execute('static_location', {location: 'Berlin'})));

    expect(compile).toHaveBeenCalledTimes(1);
  });

  it('validates each call against the schema the definition function returns at that call', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn<() => Promise<string>>().mockResolvedValue('sunny');
    let acceptsLocation = true;
    registry.register(
      () => ({
        name: 'changing_schema',
        description: 'Changes its accepted input',
        inputSchema: acceptsLocation
          ? {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}
          : {type: 'object', properties: {postalCode: {type: 'string'}}, required: ['postalCode']},
      }),
      executor
    );

    await expect(registry.execute('changing_schema', {location: 'Berlin'})).resolves.toEqual({result: 'sunny'});
    acceptsLocation = false;
    const response = await registry.execute('changing_schema', {location: 'Berlin'});

    expect({result: response.result, executorCalls: executor.mock.calls.length}).toEqual({
      result: expect.stringMatching(/postalCode.*required|required.*postalCode/i),
      executorCalls: 1,
    });
  });
});
